// GemRB Core Architectural Interfaces for Autonomous Implementation

#include <string>
#include <vector>
#include <memory>
#include <cstdint>

namespace GemRB {

struct ResRef {
    char name[8];
    uint16_t type;
};

struct ResourceBuffer {
    const uint8_t* data;
    size_t size;
};

class IResourceManager {
public:
    virtual ~IResourceManager() = default;
    virtual bool Initialize(const std::string& chitinKeyPath, const std::string& overrideDir) = 0;
    virtual std::shared_ptr<ResourceBuffer> LoadResource(const ResRef& resRef) = 0;
    virtual bool Exists(const ResRef& resRef) = 0;
};

class IGameControl {
public:
    virtual ~IGameControl() = default;
    virtual void StepTick(uint32_t deltaMs) = 0;
    virtual void TogglePause(bool userTriggered) = 0;
    virtual bool IsPaused() const = 0;
    virtual uint32_t GetCurrentTick() const = 0;
    virtual uint32_t GetCurrentRound() const = 0;
};

class IScriptEngine {
public:
    virtual ~IScriptEngine() = default;
    virtual bool EvaluateTrigger(uint32_t triggerId, const std::vector<int32_t>& intArgs, const std::string& strArg) = 0;
    virtual void ExecuteAction(uint32_t actionId, const std::vector<int32_t>& intArgs, const std::string& strArg) = 0;
};

class IRulesEngine {
public:
    virtual ~IRulesEngine() = default;
    virtual bool ResolveAttack(int32_t attackerThac0, int32_t targetAc, int32_t attackBonus, int32_t& outDamage) = 0;
    virtual bool ResolveSavingThrow(int32_t saveCategory, int32_t targetValue, int32_t modifier) = 0;
};

class IPathfinder {
public:
    virtual ~IPathfinder() = default;
    virtual std::vector<std::pair<int, int>> FindPath(int startX, int startY, int endX, int endY, int actorRadius) = 0;
    virtual bool IsPassable(int x, int y, uint32_t passabilityMask) = 0;
};

} // namespace GemRB
